rsql select json_extract(more('log_players', _more), '$') from log_players where level = 'NFL' and season = 2034 and person__player__position = 'IOL' limit 1
rsql select k.key, substr(k.value,1,100) from log_players lp, json_each(more('log_players', lp._more), '$') k where lp.level = 'NFL' and lp.season = 2034 and lp.person__player__position = 'IOL' and lp._row = (select min(_row) from log_players where level = 'NFL' and season = 2034 and person__player__position = 'IOL')
